public interface Vehicle {
    String getBrand();

    // Default method providing fallback implementation
    default void startEngine() {
        System.out.println("Starting default engine for " + getBrand());
    }

    // Static utility method associated with the interface
    static boolean isHeavyVehicle(Vehicle v) {
        return v.getBrand().equalsIgnoreCase("Truck");
    }
}

public class Car implements Vehicle {
    private final String brand;

    public Car(String brand) {
        this.brand = brand;
    }

    @Override
    public String getBrand() {
        return brand;
    }

    // Inherits startEngine() automatically, but can override it:
    @Override
    public void startEngine() {
        Vehicle.super.startEngine();
        System.out.println("Car-specific electronic ignition engaged.");
    }
}
